import { randomInt, randomUUID } from "node:crypto"; import type { DiscardView, MatchMode, MatchRankingView, MeldView, PublicActionKind, PublicActionView, ReactionOption, RoomSnapshot, RoundHistoryView, ScorePaymentView, TileCode, TurnOperationOption } from "../../shared/protocol.js"; import {   analyzeWinningHand,   createInitialGame,   drawTileFromWall,   drawTileFromWallEnd,   findDiscardReactionOptions,   findTurnOperationOptions,   selectReactionClaims,   sortTiles,   wallCountsForGame,   GAME_MODEL_VERSION,   type InitialGameState,   type Tile, } from "./game-model.js"; import { calculateHuPayments, calculateKongPayments, calculateScoreDeltas } from "./scoring.js"; import { logWarn } from "./logger.js"; import { RoomStore } from "./room-store.js";  type Player = {   id: string;   token: string;   name: string;   avatar: string;   seat: number;   ready: boolean;   connected: boolean;   isTestPlayer: boolean;   disconnectedAt?: number;   autoManaged: boolean; };  type Spectator = {   id: string;   token: string;   name: string;   avatar: string;   connected: boolean;   requestingSeat: boolean;   joinedAt: number; };  type Room = {   code: string;   revision: number;   phase: "waiting" | "playing";   hostPlayerId: string;   players: Player[];   spectators: Spectator[];   scoreTotals: number[];   startScore: number;   totalRounds: MatchMode;   completedRounds: number;   matchEndReason?: "round_limit" | "negative_score" | "early_agreement";   roundHistory: RoundHistoryView[];   publicActions: PublicActionView[];   nextActionSequence: number;   earlySettlement?: {     requesterSeat: number;     duringRound: boolean;     status: "voting" | "rejected" | "approved";     responses: Map<number, boolean>;   };   actionDeadlineAt?: number;   actionStateKey?: string;   testPlayerAutoDueAt?: number;   game?: InitialGameState; };  export type RoomManagerOptions = {   /** 测试玩家两次出牌之间的延迟；0 表示测试环境里立即出牌。 */   testPlayerTurnMs?: number; };  export type Session = {   roomCode: string;   playerId: string;   playerToken: string;   role: "player" | "spectator";   snapshot: RoomSnapshot;   autoManagementReleased?: boolean; };  export const START_SCORE_MIN = 50; export const START_SCORE_MAX = 1000;  export const AVATAR_IDS = ["a1", "a2", "a3", "a4", "a5", "a6", "a7", "a8", "a9", "a10"] as const; export const DEFAULT_AVATAR = "a1";  export const DISCARD_TIMEOUT_MS = 30_000; export const REACTION_TIMEOUT_MS = 12_000; export const AUTO_MANAGEMENT_AFTER_MS = 90_000; export const TEST_PLAYER_TURN_MS = 1_500; export const MAX_SPECTATORS = 20;  export type GovernanceEvent =   | { kind: "auto_management_started"; seat: number; offlineMs: number }   | { kind: "turn_timed_out"; seat: number; tile: TileCode; autoManaged: boolean; deadlineAt?: number; automaticTurnCount: number }   | { kind: "reaction_timed_out"; seats: number[]; autoManagedSeats: number[]; deadlineAt?: number }   | { kind: "test_player_auto_discard"; seat: number; tile: TileCode; dueAt: number; automaticTurnCount: number };  export type GovernanceTickResult = {   roomCode: string;   snapshot: RoomSnapshot;   events: GovernanceEvent[]; };  export type TurnProgress = {   snapshot: RoomSnapshot;   diagnostics: {     initialDiscard: { seat: number; tile: TileCode; handTileCount: number };     autoDiscards: Array<{ seat: number; tile: TileCode; wallRemaining: number }>;     reactionWindows: ReactionWindowDiagnostic[];     nextTurnSeat?: number;     wallRemaining: number;     nextHandTileCount?: number;     stage: NonNullable<RoomSnapshot["game"]>["stage"];   }; };  export type ReactionProgress = {   snapshot: RoomSnapshot;   diagnostics: {     responderSeat: number;     operationId: string | "pass";     resolution:       | "waiting"       | "all_passed"       | "meld_claimed"       | "discard_hu"       | "rob_kong_hu"       | "added_gang_completed"       | "special_gang_completed"       | "zhangmao_completed";     winningSeats: number[];     scorePayments: ScorePaymentView[];     claimedMeld?: MeldView;     autoDiscards: Array<{ seat: number; tile: TileCode; wallRemaining: number }>;     reactionWindows: ReactionWindowDiagnostic[];     nextTurnSeat?: number;     wallRemaining: number;     stage: NonNullable<RoomSnapshot["game"]>["stage"];   }; };  export type TurnOperationProgress = {   snapshot: RoomSnapshot;   diagnostics: {     seat: number;     operation: TurnOperationOption["kind"];     tile?: TileCode;     meld?: MeldView;     reactionWindow?: ReactionWindowDiagnostic;     scorePayments: ScorePaymentView[];     wallRemaining: number;     stage: NonNullable<RoomSnapshot["game"]>["stage"];   }; };  export type EarlySettlementProgress = {   snapshot: RoomSnapshot;   diagnostics: {     requesterSeat: number;     responderSeat?: number;     agree?: boolean;     status: "voting" | "rejected" | "approved";     approvedCount: number;     waitingCount: number;     autoApprovedSeats: number[];   }; };  export type LeaveRoomResult = {   roomCode: string;   playerId: string;   seat?: number;   wasHost: boolean;   nextHostPlayerId?: string;   deleted: boolean;   snapshot?: RoomSnapshot; };  export type AdminSpectatorView = {   id: string;   name: string;   avatar: string;   connected: boolean;   requestingSeat: boolean;   joinedSeconds: number; };  export type AdminRoomPlayerView = {   name: string;   avatar: string;   seat: number;   ready: boolean;   connected: boolean;   isHost: boolean;   isTestPlayer: boolean;   autoManaged: boolean;   offlineSeconds?: number; };  export type AdminRoomSummary = {   code: string;   phase: Room["phase"];   playerCount: number;   spectatorCount: number;   connectedPlayerCount: number;   realPlayerCount: number;   testPlayerCount: number;   readyCount: number;   totalRounds: MatchMode;   completedRounds: number;   matchStatus: "waiting" | "active" | "completed";   matchEndReason?: "round_limit" | "negative_score" | "early_agreement";   hostName?: string;   roundNumber?: number;   stage?: NonNullable<RoomSnapshot["game"]>["stage"];   wallRemaining?: number;   scoreTotals: number[];   publicActionCount: number; };  export type AdminRoomDetail = {   code: string;   revision: number;   phase: Room["phase"];   players: AdminRoomPlayerView[];   spectators: AdminSpectatorView[];   scoreTotals: number[];   match: RoomSnapshot["match"];   publicActions: PublicActionView[];   game?: {     modelVersion: string;     roundNumber: number;     dealerSeat: number;     turnSeat: number;     stage: NonNullable<RoomSnapshot["game"]>["stage"];     wallRemaining: number;     handTileCounts: number[];     actionDeadlineAt?: number;     actionTimeoutSeconds?: number;     latestDiscard?: DiscardView;     discards: DiscardView[];     melds: MeldView[];     scorePayments: ScorePaymentView[];     scoreDeltas: number[];     reaction?: NonNullable<RoomSnapshot["game"]>["reaction"];     roundResult?: NonNullable<RoomSnapshot["game"]>["roundResult"];   }; };  export type AdminStats = {   roomCount: number;   waitingRoomCount: number;   playingRoomCount: number;   spectatorCount: number;   connectedPlayerCount: number;   realPlayerCount: number;   testPlayerCount: number; };  export type AdminForceCloseResult = {   roomCode: string;   reason: string;   playerSeats: number[]; };  export type PersistedRoomEnvelope = {   schemaVersion: 1;   gameModelVersion: string;   savedAt: string;   rooms: Array<PersistedRoom>; };  type PersistedGame = Omit<InitialGameState, "hands" | "melds" | "pendingReaction"> & {   hands: Array<[number, Tile[]]>;   melds: Array<[number, MeldView[]]>;   pendingReaction?: Omit<NonNullable<InitialGameState["pendingReaction"]>, "optionsBySeat" | "responses"> & {     optionsBySeat: Array<[number, ReactionOption[]]>;     responses: Array<[number, string | "pass"]>;   }; };  type PersistedRoom = Omit<Room, "earlySettlement" | "game"> & {   earlySettlement?: Omit<NonNullable<Room["earlySettlement"]>, "responses"> & {     responses: Array<[number, boolean]>;   };   game?: PersistedGame; };  type ReactionWindowDiagnostic = {   discard: DiscardView;   eligibleSeats: number[];   optionCount: number;   autoPassedSeats: number[];   awaitingSeats: number[];   resolution: "awaiting_players" | "advance_turn"; };  type AutomaticProgress = {   autoDiscards: Array<{ seat: number; tile: TileCode; wallRemaining: number }>;   reactionWindows: ReactionWindowDiagnostic[]; };  function isRecord(value: unknown): value is Record<string, unknown> {   return typeof value === "object" && value !== null; }  export class RoomError extends Error {   constructor(     public readonly code: string,     message: string,   ) {     super(message);   } }  export class RoomManager {   private readonly rooms = new Map<string, Room>();    constructor(     private readonly gameRandomIndex: (maxExclusive: number) => number = randomInt,     private readonly gameFactory: typeof createInitialGame = createInitialGame,     private readonly now: () => number = Date.now,     private readonly store?: RoomStore,     private readonly options: RoomManagerOptions = {},   ) {}    createRoom(rawName: string, totalRounds: MatchMode = 8, startScore = 100, rawAvatar?: string): Session {     const name = this.normalizeName(rawName);     const avatar = this.normalizeAvatar(rawAvatar);     if (totalRounds !== 8 && totalRounds !== 16) throw new RoomError("MATCH_MODE_INVALID", "房间局数只能选择8局或16局");     const normalizedStartScore = this.normalizeStartScore(startScore);     const code = this.createCode();     const player = this.createPlayer(name, 0, false, avatar);     const room: Room = {       code,       revision: 1,       phase: "waiting",       hostPlayerId: player.id,       players: [player],       spectators: [],       scoreTotals: [normalizedStartScore, normalizedStartScore, normalizedStartScore, normalizedStartScore],       startScore: normalizedStartScore,       totalRounds,       completedRounds: 0,       roundHistory: [],       publicActions: [],       nextActionSequence: 1,     };     this.rooms.set(code, room);     return this.toSession(room, player);   }    joinRoom(rawCode: string, rawName: string, rawAvatar?: string, asSpectator = false): Session {     const room = this.getRoom(rawCode);     if (asSpectator || room.players.length >= 4 || room.phase !== "waiting") return this.joinAsSpectator(room, rawName, rawAvatar);     const name = this.normalizeName(rawName);     const avatar = this.normalizeAvatar(rawAvatar);     const occupied = new Set(room.players.map((player) => player.seat));     const seat = [0, 1, 2, 3].find((candidate) => !occupied.has(candidate));     if (seat === undefined) throw new RoomError("ROOM_FULL", "房间已经坐满 4 人");     const player = this.createPlayer(name, seat, false, avatar);     room.players.push(player);     room.revision += 1;     return this.toSession(room, player);   }    private joinAsSpectator(room: Room, rawName: string, rawAvatar?: string): Session {     if (room.spectators.length >= MAX_SPECTATORS) {       throw new RoomError("SPECTATOR_LIMIT", `观战人数已满（${MAX_SPECTATORS}人）`);     }     const name = this.normalizeName(rawName);     const avatar = this.normalizeAvatar(rawAvatar);     const spectator = this.createSpectator(name, avatar);     room.spectators.push(spectator);     room.revision += 1;     return {       roomCode: room.code,       playerId: spectator.id,       playerToken: spectator.token,       role: "spectator",       snapshot: this.snapshotForPlayer(room.code, spectator.token),     };   }    updateAvatar(rawCode: string, playerToken: string, rawAvatar?: string): RoomSnapshot {     const room = this.getRoom(rawCode);     const player = room.players.find((candidate) => candidate.token === playerToken)       ?? room.spectators.find((candidate) => candidate.token === playerToken);     if (!player) throw new RoomError("TOKEN_INVALID", "身份已失效");     const avatar = this.normalizeAvatar(rawAvatar);     if (player.avatar !== avatar) {       player.avatar = avatar;       room.revision += 1;     }     return this.snapshot(room.code);   }    requestSeat(rawCode: string, playerToken: string): RoomSnapshot {     const room = this.getRoom(rawCode);     if (room.phase !== "waiting") throw new RoomError("GAME_STARTED", "牌局已经开始，暂时不能上桌");     const spectator = room.spectators.find((candidate) => candidate.token === playerToken);     if (!spectator) throw new RoomError("TOKEN_INVALID", "只有观战者可以申请上桌");     if (!spectator.requestingSeat) {       spectator.requestingSeat = true;       room.revision += 1;     }     return this.snapshot(room.code);   }    promoteSpectator(rawCode: string, operatorToken: string, spectatorId: string): RoomSnapshot {     const room = this.getRoom(rawCode);     if (room.phase !== "waiting") throw new RoomError("GAME_STARTED", "牌局已经开始，不能安排上桌");     const operator = room.players.find((candidate) => candidate.token === operatorToken);     if (!operator) throw new RoomError("TOKEN_INVALID", "操作者身份已失效");     if (operator.id !== room.hostPlayerId) throw new RoomError("HOST_REQUIRED", "只有房主可以安排观战者上桌");     const spectator = room.spectators.find((candidate) => candidate.id === spectatorId);     if (!spectator) throw new RoomError("SPECTATOR_NOT_FOUND", "观战者已离开房间");     if (!spectator.connected) throw new RoomError("SPECTATOR_OFFLINE", "该观战者已离线，请等待其重连");     const occupied = new Set(room.players.map((player) => player.seat));     const seat = [0, 1, 2, 3].find((candidate) => !occupied.has(candidate));     if (seat === undefined) throw new RoomError("ROOM_FULL", "四个座位都已坐满");     const player: Player = {       id: spectator.id,       token: spectator.token,       name: spectator.name,       avatar: spectator.avatar,       seat,       ready: false,       connected: true,       isTestPlayer: false,       autoManaged: false,     };     room.players.push(player);     room.spectators = room.spectators.filter((candidate) => candidate.id !== spectator.id);     room.revision += 1;     return this.snapshot(room.code);   }    reconnect(rawCode: string, playerToken: string): Session {     const room = this.getRoom(rawCode);     const player = room.players.find((candidate) => candidate.token === playerToken);     if (player) {       let autoManagementReleased = false;       if (!player.connected) {         player.connected = true;         player.disconnectedAt = undefined;         if (player.autoManaged) {           player.autoManaged = false;           autoManagementReleased = true;           if (room.game) this.recordPublicAction(room, { kind: "auto_management_ended", seat: player.seat });         }         if (room.game) this.recordPublicAction(room, { kind: "player_reconnected", seat: player.seat });         room.revision += 1;       }       return { ...this.toSession(room, player), autoManagementReleased };     }     const spectator = room.spectators.find((candidate) => candidate.token === playerToken);     if (!spectator) throw new RoomError("TOKEN_INVALID", "身份已失效，请重新加入");     if (!spectator.connected) {       spectator.connected = true;       room.revision += 1;     }     return {       roomCode: room.code,       playerId: spectator.id,       playerToken: spectator.token,       role: "spectator",       snapshot: this.snapshotForPlayer(room.code, spectator.token),     };   }    disconnect(rawCode: string, playerToken: string): void {     const room = this.rooms.get(this.normalizeCode(rawCode));     const player = room?.players.find((candidate) => candidate.token === playerToken);     if (room && player?.connected) {       player.connected = false;       player.disconnectedAt = this.now();       if (room.game) this.recordPublicAction(room, { kind: "player_disconnected", seat: player.seat });       room.revision += 1;       return;     }     const spectator = room?.spectators.find((candidate) => candidate.token === playerToken);     if (room && spectator?.connected) {       spectator.connected = false;       room.revision += 1;     }   }    leaveRoom(rawCode: string, playerToken: string): LeaveRoomResult {     const room = this.getRoom(rawCode);     const spectator = room.spectators.find((candidate) => candidate.token === playerToken);     if (spectator) {       room.spectators = room.spectators.filter((candidate) => candidate.token !== playerToken);       room.revision += 1;       return {         roomCode: room.code,         playerId: spectator.id,         wasHost: false,         deleted: false,         snapshot: this.snapshot(room.code),       };     }     if (room.phase !== "waiting" && !room.matchEndReason) throw new RoomError("GAME_STARTED", "牌局进行中不能退出座位，请等待重连");     const player = room.players.find((candidate) => candidate.token === playerToken);     if (!player || player.isTestPlayer) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     const wasHost = player.id === room.hostPlayerId;     room.players = room.players.filter((candidate) => candidate.id !== player.id);      let nextHostPlayerId: string | undefined;     if (wasHost) {       const nextHost = room.players.find((candidate) => !candidate.isTestPlayer);       if (!nextHost) {         this.rooms.delete(room.code);         return { roomCode: room.code, playerId: player.id, seat: player.seat, wasHost, deleted: true };       }       room.hostPlayerId = nextHost.id;       nextHostPlayerId = nextHost.id;     }     room.revision += 1;     return {       roomCode: room.code,       playerId: player.id,       seat: player.seat,       wasHost,       nextHostPlayerId,       deleted: false,       snapshot: this.snapshot(room.code),     };   }    setReady(rawCode: string, playerToken: string, ready: boolean): RoomSnapshot {     const room = this.getRoom(rawCode);     const roundEnded = room.game?.stage === "round_ended" && !room.matchEndReason;     if (room.phase !== "waiting" && !roundEnded) throw new RoomError("GAME_STARTED", "本局已经开始");     const player = room.players.find((candidate) => candidate.token === playerToken);     if (!player) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     if (player.ready !== ready) {       player.ready = ready;       room.revision += 1;     }     return this.snapshot(room.code);   }    fillWithTestPlayers(rawCode: string, playerToken: string): RoomSnapshot {     const room = this.getRoom(rawCode);     if (room.phase !== "waiting") throw new RoomError("GAME_STARTED", "本局已经开始");     const operator = room.players.find((candidate) => candidate.token === playerToken);     if (!operator) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     if (operator.id !== room.hostPlayerId) throw new RoomError("HOST_REQUIRED", "只有房主可以添加测试玩家");     let testNumber = room.players.filter((player) => player.isTestPlayer).length + 1;     while (room.players.length < 4) {       const occupied = new Set(room.players.map((player) => player.seat));       const seat = [0, 1, 2, 3].find((candidate) => !occupied.has(candidate));       if (seat === undefined) break;       const player = this.createPlayer(`测试玩家${testNumber}`, seat, true, `a${seat + 1}`);       player.ready = true;       room.players.push(player);       testNumber += 1;     }     room.revision += 1;     return this.snapshot(room.code);   }    removeTestPlayers(rawCode: string, playerToken: string): { snapshot: RoomSnapshot; removedCount: number } {     const room = this.getRoom(rawCode);     if (room.phase !== "waiting") throw new RoomError("GAME_STARTED", "本局已经开始");     const operator = room.players.find((candidate) => candidate.token === playerToken);     if (!operator) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     if (operator.id !== room.hostPlayerId) throw new RoomError("HOST_REQUIRED", "只有房主可以移除测试玩家");     const previousCount = room.players.length;     room.players = room.players.filter((player) => !player.isTestPlayer);     const removedCount = previousCount - room.players.length;     if (removedCount > 0) room.revision += 1;     return { snapshot: this.snapshot(room.code), removedCount };   }    startGame(rawCode: string, playerToken: string): RoomSnapshot {     const room = this.getRoom(rawCode);     const operator = room.players.find((candidate) => candidate.token === playerToken);     if (!operator) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     if (operator.id !== room.hostPlayerId) throw new RoomError("HOST_REQUIRED", "只有房主可以开始游戏");     if (room.phase !== "waiting") throw new RoomError("GAME_STARTED", "本局已经开始");     if (room.players.length !== 4) throw new RoomError("PLAYERS_REQUIRED", "需要四名玩家才能开始");     if (!room.players.every((player) => player.ready)) throw new RoomError("READY_REQUIRED", "需要所有玩家准备后才能开始");     if (!room.players.every((player) => player.connected || player.isTestPlayer)) {       throw new RoomError("CONNECTED_PLAYERS_REQUIRED", "有玩家暂时离线，请等待其重连后再开始");     }     const hasTestPlayers = room.players.some((player) => player.isTestPlayer);     const dealerCandidates = hasTestPlayers ? room.players.filter((player) => !player.isTestPlayer) : room.players;     const dealerSeat = dealerCandidates[this.gameRandomIndex(dealerCandidates.length)]!.seat;     room.game = this.gameFactory(       room.players.map((player) => player.seat),       dealerSeat,       this.gameRandomIndex,     );     room.phase = "playing";     this.recordPublicAction(room, { kind: "round_started", roundNumber: room.game.roundNumber, seat: dealerSeat });     this.ensureActionDeadline(room, true);     room.revision += 1;     return this.maybeAdvanceTestDealer(room) ?? this.snapshot(room.code);   }    startNextRound(rawCode: string, playerToken: string): RoomSnapshot {     const room = this.getRoom(rawCode);     const operator = room.players.find((candidate) => candidate.token === playerToken);     if (!operator) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     if (operator.id !== room.hostPlayerId) throw new RoomError("HOST_REQUIRED", "只有房主可以开始下一局");     if (room.phase !== "playing" || !room.game) throw new RoomError("GAME_NOT_STARTED", "牌局尚未开始");     if (room.matchEndReason) throw new RoomError("MATCH_ENDED", "整场游戏已经结束");     if (room.earlySettlement?.status === "voting") throw new RoomError("EARLY_SETTLEMENT_PENDING", "提前结算投票尚未结束");     if (room.game.stage !== "round_ended" || !room.game.roundResult) throw new RoomError("ROUND_ACTIVE", "本局尚未结束");     if (!room.players.every((player) => player.ready)) throw new RoomError("READY_REQUIRED", "需要所有玩家准备后才能开始下一局");      const previous = room.game;     const previousResult = previous.roundResult;     if (!previousResult) throw new RoomError("ROUND_ACTIVE", "本局尚未结束");     const dealerContinues = previousResult.reason === "wall_exhausted"       || previousResult.winnerSeats.includes(previous.dealerSeat);     const hasTestPlayers = room.players.some((player) => player.isTestPlayer);     const realSeats = room.players.filter((player) => !player.isTestPlayer).map((player) => player.seat).sort((left, right) => left - right);     const previousDealer = room.players.find((player) => player.seat === previous.dealerSeat);     const nextDealerSeat = !hasTestPlayers       ? (dealerContinues ? previous.dealerSeat : (previous.dealerSeat + 1) % 4)       : dealerContinues && previousDealer && !previousDealer.isTestPlayer         ? previous.dealerSeat         : (realSeats.find((seat) => seat > previous.dealerSeat) ?? realSeats[0] ?? previous.dealerSeat);     const nextRoundNumber = previous.roundNumber + 1;     const nextGame = this.gameFactory(       room.players.map((player) => player.seat),       nextDealerSeat,       this.gameRandomIndex,       nextRoundNumber,     );     nextGame.roundNumber = nextRoundNumber;     room.game = nextGame;     room.earlySettlement = undefined;     this.recordPublicAction(room, { kind: "round_started", roundNumber: nextRoundNumber, seat: nextDealerSeat });     this.ensureActionDeadline(room, true);     room.revision += 1;     return this.maybeAdvanceTestDealer(room) ?? this.snapshot(room.code);   }    requestEarlySettlement(rawCode: string, playerToken: string): EarlySettlementProgress {     const room = this.getRoom(rawCode);     const player = room.players.find((candidate) => candidate.token === playerToken);     if (!player) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     if (room.phase !== "playing" || !room.game) throw new RoomError("GAME_NOT_STARTED", "牌局尚未开始");     if (room.matchEndReason) throw new RoomError("MATCH_ENDED", "整场游戏已经结束");     if (room.earlySettlement?.status === "voting") throw new RoomError("EARLY_SETTLEMENT_PENDING", "已经有一项提前结算投票");      const duringRound = room.game.stage !== "round_ended";     const autoApprovedSeats = room.players.filter((candidate) => candidate.isTestPlayer).map((candidate) => candidate.seat);     const responses = new Map<number, boolean>([[player.seat, true], ...autoApprovedSeats.map((seat) => [seat, true] as const)]);     const status = responses.size === room.players.length ? "approved" : "voting";     room.earlySettlement = { requesterSeat: player.seat, duringRound, status, responses };     this.recordPublicAction(room, { kind: "settlement_requested", seat: player.seat });     this.clearActionDeadline(room);     if (status === "approved") this.finalizeEarlySettlement(room);     room.revision += 1;     return {       snapshot: this.snapshot(room.code),       diagnostics: {         requesterSeat: player.seat,         status,         approvedCount: responses.size,         waitingCount: room.players.length - responses.size,         autoApprovedSeats,       },     };   }    respondEarlySettlement(rawCode: string, playerToken: string, agree: boolean): EarlySettlementProgress {     const room = this.getRoom(rawCode);     const player = room.players.find((candidate) => candidate.token === playerToken);     if (!player) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     if (room.matchEndReason) throw new RoomError("MATCH_ENDED", "整场游戏已经结束");     const vote = room.earlySettlement;     if (!vote || vote.status !== "voting") throw new RoomError("EARLY_SETTLEMENT_NOT_AVAILABLE", "当前没有等待表态的提前结算投票");     if (vote.responses.has(player.seat)) throw new RoomError("EARLY_SETTLEMENT_ALREADY_SENT", "你已经对提前结算表态");      vote.responses.set(player.seat, agree);     this.recordPublicAction(room, { kind: agree ? "settlement_agreed" : "settlement_rejected", seat: player.seat });     if (!agree) vote.status = "rejected";     else if (vote.responses.size === room.players.length) {       vote.status = "approved";       this.finalizeEarlySettlement(room);     }     if (vote.status === "rejected") this.ensureActionDeadline(room, true);     room.revision += 1;     return {       snapshot: this.snapshot(room.code),       diagnostics: {         requesterSeat: vote.requesterSeat,         responderSeat: player.seat,         agree,         status: vote.status,         approvedCount: [...vote.responses.values()].filter(Boolean).length,         waitingCount: vote.status === "voting" ? room.players.length - vote.responses.size : 0,         autoApprovedSeats: [],       },     };   }    discardTile(rawCode: string, playerToken: string, tileCode: TileCode): TurnProgress {     const room = this.getRoom(rawCode);     const player = room.players.find((candidate) => candidate.token === playerToken);     if (!player) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     if (room.phase !== "playing" || !room.game) throw new RoomError("GAME_REQUIRED", "牌局尚未开始");     if (room.earlySettlement?.status === "voting") throw new RoomError("EARLY_SETTLEMENT_PENDING", "解散投票进行中，牌局已暂停");     if (room.game.stage === "round_ended") throw new RoomError("ROUND_ENDED", "本局已经结束");     if (room.game.stage !== "awaiting_discard") throw new RoomError("REACTIONS_PENDING", "请等待其他玩家响应当前弃牌");     if (room.game.turnSeat !== player.seat) throw new RoomError("TURN_REQUIRED", "还没有轮到你出牌");     const hand = room.game.hands.get(player.seat);     const tileIndex = hand?.findIndex((tile) => tile.code === tileCode) ?? -1;     if (!hand || tileIndex < 0) throw new RoomError("TILE_NOT_IN_HAND", "你的手牌中没有这张牌");     if (room.game.discardRestriction?.seat === player.seat && room.game.discardRestriction.tile === tileCode) {       throw new RoomError("CHI_DISCARD_RESTRICTED", "刚吃的这张牌本回合不能打出");     }      hand.splice(tileIndex, 1);     if (room.game.discardRestriction?.seat === player.seat) room.game.discardRestriction = undefined;     const initialHandTileCount = hand.length;     room.game.discards.push({ seat: player.seat, tile: tileCode });     room.game.stage = "awaiting_reactions";     room.game.lastDraw = undefined;     const progress: AutomaticProgress = { autoDiscards: [], reactionWindows: [] };     this.recordPublicAction(room, { kind: "discard", seat: player.seat, tile: tileCode });     this.progressFromDiscard(room, { seat: player.seat, tile: tileCode }, progress);     this.updateMatchAfterRound(room);     for (const automatic of progress.autoDiscards) {       this.recordPublicAction(room, { kind: "discard", seat: automatic.seat, tile: automatic.tile });     }     this.recordRoundEndedAction(room);     this.ensureActionDeadline(room, true);     room.revision += 1;     const nextTurnSeat = room.game.lastDraw ? room.game.turnSeat : undefined;     return {       snapshot: this.snapshot(room.code),       diagnostics: {         initialDiscard: { seat: player.seat, tile: tileCode, handTileCount: initialHandTileCount },         autoDiscards: progress.autoDiscards,         reactionWindows: progress.reactionWindows,         nextTurnSeat,         wallRemaining: room.game.wall.length,         nextHandTileCount: nextTurnSeat === undefined ? undefined : room.game.hands.get(nextTurnSeat)?.length,         stage: room.game.stage,       },     };   }    performTurnOperation(rawCode: string, playerToken: string, operationId: string): TurnOperationProgress {     const room = this.getRoom(rawCode);     const player = room.players.find((candidate) => candidate.token === playerToken);     if (!player) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     const game = room.game;     if (room.phase !== "playing" || !game) throw new RoomError("GAME_REQUIRED", "牌局尚未开始");     if (room.earlySettlement?.status === "voting") throw new RoomError("EARLY_SETTLEMENT_PENDING", "解散投票进行中，牌局已暂停");     if (game.stage === "round_ended") throw new RoomError("ROUND_ENDED", "本局已经结束");     if (game.stage !== "awaiting_discard" || game.turnSeat !== player.seat) {       throw new RoomError("TURN_OPERATION_NOT_AVAILABLE", "当前不能执行这个回合操作");     }     const hand = game.hands.get(player.seat);     const melds = game.melds.get(player.seat);     if (!hand || !melds) throw new Error("当前玩家牌组不存在");     const scorePaymentStart = game.scorePayments.length;     const option = findTurnOperationOptions(hand, player.seat, melds, game.lastDraw, game.wall.length).find(       (candidate) => candidate.id === operationId,     );     if (!option) throw new RoomError("TURN_OPERATION_INVALID", "这个操作不在当前可选范围内");      let tile: TileCode | undefined;     let meld: MeldView | undefined;     let reactionWindow: ReactionWindowDiagnostic | undefined;     let autoResolvedKongReaction: ReactionProgress | undefined;     let directKongFinalized = false;     let kongReactionFullyResolved = false;     if (option.kind === "zimo") {       tile = game.lastDraw?.tile.code;       const analysis = analyzeWinningHand(hand, undefined, melds);       const settlement = calculateHuPayments({         winnerSeats: [player.seat],         dealerSeat: game.dealerSeat,         reason: "self_draw_hu",         analyses: new Map([[player.seat, analysis]]),         meldsBySeat: game.melds,       });       this.recordPayments(room, settlement.payments);       game.pendingReaction = undefined;       game.lastDraw = undefined;       game.stage = "round_ended";       game.roundResult = {         reason: "self_draw_hu",         winnerSeats: [player.seat],         tile,         winnerDetails: settlement.winnerDetails,         payments: [...game.scorePayments],         scoreDeltas: [...game.scoreDeltas],       };     } else if (option.kind === "angang") {       tile = option.tiles[0];       if (!tile) throw new Error("暗杠牌张不存在");       this.removeTilesFromHand(hand, option.tiles);       meld = { seat: player.seat, kind: "gang", gangType: "an", tiles: [...option.tiles], fromSeat: player.seat };       melds.push(meld);       game.lastDraw = undefined;       drawTileFromWallEnd(game, player.seat);     } else {       const parts = option.id.split(":");       const meldIndex = option.kind === "jiagang" || option.kind === "zhangmao" ? Number(parts[1]) : undefined;       const specialType = option.kind === "specialgang" ? (parts[1] as "dragons" | "winds") : undefined;       tile = option.kind === "specialgang" && game.lastDraw?.seat === player.seat && option.tiles.includes(game.lastDraw.tile.code)         ? game.lastDraw.tile.code         : option.tiles.at(-1) ?? option.tiles[0];       if (!tile || ((option.kind === "jiagang" || option.kind === "zhangmao") && !Number.isInteger(meldIndex))) {         throw new Error("可抢杠操作状态不一致");       }       const physicalTiles = this.takeTilesFromHand(hand, option.tiles);       const discard = { seat: player.seat, tile };       const optionsBySeat = new Map<number, ReactionOption[]>();       for (const candidate of room.players) {         if (candidate.seat === player.seat) continue;         const candidateHand = game.hands.get(candidate.seat) ?? [];         const huOptions = findDiscardReactionOptions(           candidateHand,           candidate.seat,           discard,           game.melds.get(candidate.seat) ?? [],           game.wall.length,         ).filter((candidateOption) => candidateOption.kind === "hu");         if (huOptions.length > 0) optionsBySeat.set(candidate.seat, huOptions);       }       const responderSeats = [...optionsBySeat.keys()];       const testResponderSeats = responderSeats.filter((seat) => room.players.find((candidate) => candidate.seat === seat)?.isTestPlayer);       const autoPassedSeats = testResponderSeats.filter((seat) => !(optionsBySeat.get(seat) ?? []).some((candidateOption) => candidateOption.kind === "hu"));       const humanResponderSeats = responderSeats.filter((seat) => !testResponderSeats.includes(seat));       reactionWindow = {         discard,         eligibleSeats: responderSeats,         optionCount: [...optionsBySeat.values()].reduce((sum, options) => sum + options.length, 0),         autoPassedSeats,         awaitingSeats: humanResponderSeats,         resolution: humanResponderSeats.length > 0 ? "awaiting_players" : "advance_turn",       };       const pendingKong: NonNullable<NonNullable<InitialGameState["pendingReaction"]>["pendingKong"]> = {         seat: player.seat,         type: option.kind,         tiles: physicalTiles,         robTile: tile,         meldIndex,         specialType,       };       const source = option.kind === "jiagang" ? "added_gang" : option.kind === "specialgang" ? "special_gang" : "zhangmao";       game.lastDraw = undefined;       if (responderSeats.length === 0) {         directKongFinalized = true;         meld = this.finalizePendingKong(game, pendingKong);       } else {         game.pendingReaction = { discard, source, pendingKong, optionsBySeat, responses: new Map() };         game.stage = "awaiting_reactions";         for (const seat of testResponderSeats) {           const responder = room.players.find((candidate) => candidate.seat === seat);           if (!responder) throw new Error("测试响应玩家不存在");           const canHu = (optionsBySeat.get(seat) ?? []).some((candidateOption) => candidateOption.kind === "hu");           autoResolvedKongReaction = this.reactToDiscard(room.code, responder.token, canHu ? "hu" : "pass");         }         if (humanResponderSeats.length === 0) {           kongReactionFullyResolved = true;           const diagnostics = autoResolvedKongReaction?.diagnostics;           if (diagnostics?.claimedMeld) meld = diagnostics.claimedMeld;         }       }     }            if (meld && option.kind !== "zimo" && (option.kind === "angang" || directKongFinalized)) {       const growthCount = option.kind === "specialgang" && meld.kind === "special_gang" ? (meld.growthCount ?? 0) : 0;       this.recordKongPayments(room, player.seat, option.kind, growthCount);     }      this.updateMatchAfterRound(room);     if (option.kind === "zimo") {       this.recordPublicAction(room, { kind: "self_draw_hu", seats: [player.seat], tile });     } else if (!kongReactionFullyResolved && meld) {       this.recordPublicAction(room, {         kind: this.publicKindForMeld(meld),         seat: player.seat,         fromSeat: meld.fromSeat,         tile: meld.gangType === "an" ? undefined : tile,       });     }     this.recordRoundEndedAction(room);     this.ensureActionDeadline(room, true);     room.revision += 1;     return {       snapshot: this.snapshot(room.code),       diagnostics: {         seat: player.seat,         operation: option.kind,         tile,         meld,         reactionWindow,         scorePayments: game.scorePayments.slice(scorePaymentStart),         wallRemaining: game.wall.length,         stage: game.stage,       },     };   }    reactToDiscard(rawCode: string, playerToken: string, operationId: string | "pass"): ReactionProgress {     const room = this.getRoom(rawCode);     const player = room.players.find((candidate) => candidate.token === playerToken);     if (!player) throw new RoomError("TOKEN_INVALID", "玩家身份已失效");     const game = room.game;     const pending = game?.pendingReaction;     if (room.earlySettlement?.status === "voting") throw new RoomError("EARLY_SETTLEMENT_PENDING", "解散投票进行中，牌局已暂停");     if (room.phase !== "playing" || !game || game.stage !== "awaiting_reactions" || !pending) {       throw new RoomError("REACTION_NOT_AVAILABLE", "当前没有等待你响应的弃牌");     }     const scorePaymentStart = game.scorePayments.length;     const options = pending.optionsBySeat.get(player.seat);     if (!options?.length) throw new RoomError("REACTION_NOT_ELIGIBLE", "你不能响应这张弃牌");     if (pending.responses.has(player.seat)) throw new RoomError("REACTION_ALREADY_SENT", "你已经响应过这张牌");     if (operationId !== "pass" && !options.some((option) => option.id === operationId)) {       throw new RoomError("REACTION_INVALID", "这个操作不在当前可选范围内");     }     pending.responses.set(player.seat, operationId);     const progress: AutomaticProgress = { autoDiscards: [], reactionWindows: [] };     let resolution: ReactionProgress["diagnostics"]["resolution"] = "waiting";     let winningSeats: number[] = [];     let claimedMeld: MeldView | undefined;     const waitingSeats = [...pending.optionsBySeat.keys()].filter((seat) => !pending.responses.has(seat));      if (waitingSeats.length === 0) {       const claims = [...pending.responses.entries()]         .filter(([, response]) => response !== "pass")         .map(([seat, response]) => ({           seat,           option: pending.optionsBySeat.get(seat)!.find((option) => option.id === response)!,         }));       const selectedClaims = selectReactionClaims(claims);       const huClaims = selectedClaims.filter((claim) => claim.option.kind === "hu");       if (huClaims.length > 0) {         winningSeats = huClaims.map((claim) => claim.seat);         if (pending.pendingKong) this.restoreUnrobbedKongTiles(game, pending.pendingKong);         const roundReason = pending.source === "discard" ? "discard_hu" : "rob_kong_hu";         const analyses = new Map(           winningSeats.map((seat) => [             seat,             analyzeWinningHand(game.hands.get(seat) ?? [], pending.discard.tile, game.melds.get(seat) ?? []),           ]),         );         const settlement = calculateHuPayments({           winnerSeats: winningSeats,           fromSeat: pending.discard.seat,           dealerSeat: game.dealerSeat,           reason: roundReason,           analyses,           meldsBySeat: game.melds,         });         this.recordPayments(room, settlement.payments);         game.pendingReaction = undefined;         game.lastDraw = undefined;         game.stage = "round_ended";         game.roundResult = {           reason: roundReason,           winnerSeats: winningSeats,           fromSeat: pending.discard.seat,           tile: pending.discard.tile,           winnerDetails: settlement.winnerDetails,           payments: [...game.scorePayments],           scoreDeltas: [...game.scoreDeltas],         };         resolution = pending.source === "discard" ? "discard_hu" : "rob_kong_hu";       } else if (selectedClaims.length > 0) {         if (pending.source !== "discard") throw new Error("加杠响应窗口只能胡牌或过牌");         const claim = selectedClaims[0]!;         claimedMeld = this.applyMeldClaim(game, pending.discard, claim.seat, claim.option);         if (claim.option.kind === "gang") this.recordKongPayments(room, claim.seat, "gang");         resolution = "meld_claimed";       } else if (pending.source !== "discard") {         if (!pending.pendingKong) throw new Error("待完成的抢杠操作不存在");         game.pendingReaction = undefined;         claimedMeld = this.finalizePendingKong(game, pending.pendingKong);         this.recordKongPayments(room, pending.pendingKong.seat, pending.pendingKong.type);         resolution = pending.source === "added_gang"           ? "added_gang_completed"           : pending.source === "special_gang"             ? "special_gang_completed"             : "zhangmao_completed";       } else {         game.pendingReaction = undefined;         this.progressFromDiscard(room, pending.discard, progress, true);         resolution = "all_passed";       }     }      this.updateMatchAfterRound(room);     if (resolution === "discard_hu" || resolution === "rob_kong_hu") {       this.recordPublicAction(room, {         kind: resolution,         seats: winningSeats,         fromSeat: pending.discard.seat,         tile: pending.discard.tile,       });     } else if (claimedMeld) {       this.recordPublicAction(room, {         kind: this.publicKindForMeld(claimedMeld),         seat: claimedMeld.seat,         fromSeat: claimedMeld.fromSeat,         tile: pending.discard.tile,       });     }     for (const automatic of progress.autoDiscards) {       this.recordPublicAction(room, { kind: "discard", seat: automatic.seat, tile: automatic.tile });     }     this.recordRoundEndedAction(room);     this.ensureActionDeadline(room, resolution !== "waiting");     room.revision += 1;     const nextTurnSeat = game.pendingReaction || game.roundResult ? undefined : game.turnSeat;     return {       snapshot: this.snapshot(room.code),       diagnostics: {         responderSeat: player.seat,         operationId,         resolution,         winningSeats,         scorePayments: game.scorePayments.slice(scorePaymentStart),         claimedMeld,         autoDiscards: progress.autoDiscards,         reactionWindows: progress.reactionWindows,         nextTurnSeat,         wallRemaining: game.wall.length,         stage: game.stage,       },     };   }    processGovernance(now = this.now()): GovernanceTickResult[] {     const results: GovernanceTickResult[] = [];     for (const room of this.rooms.values()) {       const events: GovernanceEvent[] = [];       for (const player of room.players) {         if (player.isTestPlayer || player.connected || player.autoManaged || player.disconnectedAt === undefined) continue;         const offlineMs = now - player.disconnectedAt;         if (offlineMs < AUTO_MANAGEMENT_AFTER_MS) continue;         player.autoManaged = true;         this.recordPublicAction(room, { kind: "auto_management_started", seat: player.seat });         room.revision += 1;         events.push({ kind: "auto_management_started", seat: player.seat, offlineMs });       }        const game = room.game;       if (!game || room.matchEndReason || room.earlySettlement?.status === "voting" || game.stage === "round_ended") {         if (events.length > 0) results.push({ roomCode: room.code, snapshot: this.snapshot(room.code), events });         continue;       }        const deadlineAt = room.actionDeadlineAt;       const expired = deadlineAt !== undefined && deadlineAt <= now;       if (game.stage === "awaiting_discard") {         const player = room.players.find((candidate) => candidate.seat === game.turnSeat);         const testDueAt = room.testPlayerAutoDueAt;         if (player?.isTestPlayer) {           if (testDueAt === undefined) {             this.scheduleTestPlayer(room);           } else if (testDueAt <= now) {             const fallbackTile = this.pickAutomaticDiscardTile(game, player.seat);             const autoPlay = this.autoPlayTestTurn(room, player.seat);             events.push({               kind: "test_player_auto_discard",               seat: player.seat,               tile: autoPlay.playedTile ?? fallbackTile,               dueAt: testDueAt,               automaticTurnCount: autoPlay.automaticTurnCount,             });             this.scheduleTestPlayer(room);           }         } else if (player && (player.autoManaged || expired)) {           const tile = this.pickAutomaticDiscardTile(game, player.seat);           this.recordPublicAction(room, { kind: "turn_timed_out", seat: player.seat, tile });           const progress = this.discardTile(room.code, player.token, tile);           events.push({             kind: "turn_timed_out",             seat: player.seat,             tile,             autoManaged: player.autoManaged,             deadlineAt,             automaticTurnCount: progress.diagnostics.autoDiscards.length,           });         }       } else if (game.stage === "awaiting_reactions" && game.pendingReaction) {         const waitingSeats = [...game.pendingReaction.optionsBySeat.keys()].filter(           (seat) => !game.pendingReaction?.responses.has(seat),         );         const autoManagedSeats = waitingSeats.filter(           (seat) => room.players.find((candidate) => candidate.seat === seat)?.autoManaged,         );         const timedOutSeats = expired ? waitingSeats : autoManagedSeats;         if (timedOutSeats.length > 0) {           this.recordPublicAction(room, { kind: "reaction_timed_out", seats: timedOutSeats });           for (const seat of timedOutSeats) {             const currentPending = room.game?.pendingReaction;             if (!currentPending?.optionsBySeat.has(seat) || currentPending.responses.has(seat)) continue;             const player = room.players.find((candidate) => candidate.seat === seat);             if (!player) throw new Error("自动过牌玩家不存在");             this.reactToDiscard(room.code, player.token, "pass");           }           events.push({ kind: "reaction_timed_out", seats: timedOutSeats, autoManagedSeats, deadlineAt });         }       }        if (events.length > 0) results.push({ roomCode: room.code, snapshot: this.snapshot(room.code), events });     }     return results;   }    snapshot(rawCode: string): RoomSnapshot {     const room = this.getRoom(rawCode);     return this.buildSnapshot(room);   }    snapshotForPlayer(rawCode: string, playerToken: string): RoomSnapshot {     const room = this.getRoom(rawCode);     const viewer = room.players.find((player) => player.token === playerToken)       ?? room.spectators.find((spectator) => spectator.token === playerToken);     if (!viewer) throw new RoomError("TOKEN_INVALID", "身份已失效");     return this.buildSnapshot(room, viewer);   }    participant(rawCode: string, playerToken: string): { id: string; name: string; avatar: string; seat?: number } {     const room = this.getRoom(rawCode);     const player = room.players.find((candidate) => candidate.token === playerToken);     if (player) return { id: player.id, name: player.name, avatar: player.avatar, seat: player.seat };     const spectator = room.spectators.find((candidate) => candidate.token === playerToken);     if (spectator) return { id: spectator.id, name: spectator.name, avatar: spectator.avatar };     throw new RoomError("TOKEN_INVALID", "身份已失效");   }    adminStats(): AdminStats {     const rooms = [...this.rooms.values()];     let waitingRoomCount = 0;     let playingRoomCount = 0;     let spectatorCount = 0;     let connectedPlayerCount = 0;     let realPlayerCount = 0;     let testPlayerCount = 0;     for (const room of rooms) {       if (room.phase === "waiting") waitingRoomCount += 1;       else playingRoomCount += 1;       spectatorCount += room.spectators.length;       for (const player of room.players) {         if (player.isTestPlayer) testPlayerCount += 1;         else {           realPlayerCount += 1;           if (player.connected) connectedPlayerCount += 1;         }       }     }     return { roomCount: rooms.length, waitingRoomCount, playingRoomCount, spectatorCount, connectedPlayerCount, realPlayerCount, testPlayerCount };   }    listAdminRooms(): AdminRoomSummary[] {     return [...this.rooms.values()]       .sort((left, right) => left.code.localeCompare(right.code))       .map((room) => ({         code: room.code,         phase: room.phase,         playerCount: room.players.length,         spectatorCount: room.spectators.length,         connectedPlayerCount: room.players.filter((player) => !player.isTestPlayer && player.connected).length,         realPlayerCount: room.players.filter((player) => !player.isTestPlayer).length,         testPlayerCount: room.players.filter((player) => player.isTestPlayer).length,         readyCount: room.players.filter((player) => player.ready).length,         totalRounds: room.totalRounds,         completedRounds: room.completedRounds,         matchStatus: room.matchEndReason ? "completed" : room.phase === "playing" ? "active" : "waiting",         matchEndReason: room.matchEndReason,         hostName: room.players.find((player) => player.id === room.hostPlayerId)?.name,         roundNumber: room.game?.roundNumber,         stage: room.game?.stage,         wallRemaining: room.game?.wall.length,         scoreTotals: [...room.scoreTotals],         publicActionCount: room.publicActions.length,       }));   }    getAdminRoom(rawCode: string): AdminRoomDetail {     const room = this.getRoom(rawCode);     const snapshot = this.buildSnapshot(room);     return {       code: room.code,       revision: room.revision,       phase: room.phase,       players: [...room.players]         .sort((left, right) => left.seat - right.seat)         .map((player) => ({           name: player.name,           avatar: player.avatar,           seat: player.seat,           ready: player.ready,           connected: player.connected,           isHost: player.id === room.hostPlayerId,           isTestPlayer: player.isTestPlayer,           autoManaged: player.autoManaged,           offlineSeconds: player.disconnectedAt === undefined ? undefined : Math.max(0, Math.floor((this.now() - player.disconnectedAt) / 1_000)),         })),       spectators: [...room.spectators].map((spectator) => ({         id: spectator.id,         name: spectator.name,         avatar: spectator.avatar,         connected: spectator.connected,         requestingSeat: spectator.requestingSeat,         joinedSeconds: Math.max(0, Math.floor((this.now() - spectator.joinedAt) / 1_000)),       })),       scoreTotals: [...room.scoreTotals],       match: snapshot.match,       publicActions: snapshot.publicActions,       game: snapshot.game         ? {             modelVersion: snapshot.game.modelVersion,             roundNumber: snapshot.game.roundNumber,             dealerSeat: snapshot.game.dealerSeat,             turnSeat: snapshot.game.turnSeat,             stage: snapshot.game.stage,             wallRemaining: snapshot.game.wallRemaining,             handTileCounts: [...snapshot.game.handTileCounts],             actionDeadlineAt: snapshot.game.actionDeadlineAt,             actionTimeoutSeconds: snapshot.game.actionTimeoutSeconds,             latestDiscard: snapshot.game.latestDiscard,             discards: snapshot.game.discards,             melds: snapshot.game.melds,             scorePayments: snapshot.game.scorePayments,             scoreDeltas: snapshot.game.scoreDeltas,             reaction: snapshot.game.reaction,             roundResult: snapshot.game.roundResult,           }         : undefined,     };   }    forceCloseRoomByAdmin(rawCode: string, reason = "管理员强制解散房间"): AdminForceCloseResult {     const room = this.getRoom(rawCode);     const playerSeats = room.players.map((player) => player.seat);     this.rooms.delete(room.code);     return { roomCode: room.code, reason, playerSeats };   }    exportPersistedState(): PersistedRoomEnvelope {     return {       schemaVersion: 1,       gameModelVersion: GAME_MODEL_VERSION,       savedAt: new Date().toISOString(),       rooms: [...this.rooms.values()].map((room) => this.serializeRoom(room)),     };   }    restorePersistedState(input: unknown): { restoredCount: number; skipped: string[] } {     if (!isRecord(input) || input.schemaVersion !== 1 || input.gameModelVersion !== GAME_MODEL_VERSION) {       throw new RoomError("PERSISTENCE_VERSION_MISMATCH", "持久化数据版本与当前程序不匹配");     }     if (!Array.isArray(input.rooms)) throw new RoomError("PERSISTENCE_INVALID", "持久化数据缺少房间列表");     const restored: Room[] = [];     const skipped: string[] = [];     for (const raw of input.rooms) {       try {         const room = this.deserializeRoom(raw);         if (this.rooms.has(room.code)) throw new Error("房间号重复");         restored.push(room);       } catch {         skipped.push(isRecord(raw) && typeof raw.code === "string" ? raw.code : "unknown");       }     }     this.rooms.clear();     for (const room of restored) this.rooms.set(room.code, room);     return { restoredCount: restored.length, skipped };   }    async restoreFromStore(): Promise<{ restoredCount: number; skipped: string[] }> {     if (!this.store) return { restoredCount: 0, skipped: [] };     const payload = await this.store.load();     if (!payload) return { restoredCount: 0, skipped: [] };     return this.restorePersistedState(JSON.parse(payload));   }    async persistToStore(): Promise<boolean> {     if (!this.store) return false;     try {       await this.store.save(JSON.stringify(this.exportPersistedState()));       return true;     } catch (error) {       logWarn("room_persist_failed", { message: error instanceof Error ? error.message.slice(0, 160) : "unknown" });       return false;     }   }    private serializeRoom(room: Room): PersistedRoom {     return {       ...room,       earlySettlement: room.earlySettlement         ? { ...room.earlySettlement, responses: [...room.earlySettlement.responses.entries()] }         : undefined,       game: room.game         ? {             ...room.game,             hands: [...room.game.hands.entries()],             melds: [...room.game.melds.entries()],             pendingReaction: room.game.pendingReaction               ? {                   ...room.game.pendingReaction,                   optionsBySeat: [...room.game.pendingReaction.optionsBySeat.entries()],                   responses: [...room.game.pendingReaction.responses.entries()],                 }               : undefined,           }         : undefined,     };   }    private deserializeRoom(raw: unknown): Room {     if (!isRecord(raw) || typeof raw.code !== "string" || !/^\d{6}$/.test(raw.code) || !Array.isArray(raw.players) || typeof raw.revision !== "number") {       throw new Error("房间字段不完整");     }     const gameRaw = raw.game as PersistedGame | undefined;     const game = gameRaw       ? {           ...gameRaw,           hands: new Map(gameRaw.hands),           melds: new Map(gameRaw.melds),           pendingReaction: gameRaw.pendingReaction             ? {                 ...gameRaw.pendingReaction,                 optionsBySeat: new Map(gameRaw.pendingReaction.optionsBySeat),                 responses: new Map(gameRaw.pendingReaction.responses),               }             : undefined,         }       : undefined;     const earlySettlementRaw = raw.earlySettlement as PersistedRoom["earlySettlement"] | undefined;     const earlySettlement = earlySettlementRaw       ? { ...earlySettlementRaw, responses: new Map(earlySettlementRaw.responses) }       : undefined;     const startScore = typeof raw.startScore === "number" && Number.isInteger(raw.startScore)       ? this.normalizeStartScore(raw.startScore)       : 100;     const players = Array.isArray(raw.players)       ? raw.players.map((player) => isRecord(player) ? { ...player, avatar: this.normalizeAvatar(player.avatar) } : player)       : raw.players;     const spectators = Array.isArray(raw.spectators)       ? raw.spectators           .filter(isRecord)           .map((spectator) => ({             id: typeof spectator.id === "string" ? spectator.id : randomUUID(),             token: typeof spectator.token === "string" ? spectator.token : randomUUID(),             name: typeof spectator.name === "string" ? spectator.name : "观战者",             avatar: this.normalizeAvatar(spectator.avatar),             connected: spectator.connected !== false,             requestingSeat: spectator.requestingSeat === true,             joinedAt: typeof spectator.joinedAt === "number" ? spectator.joinedAt : Date.now(),           }))       : [];     return { ...raw, players, spectators, startScore, earlySettlement, game } as Room;   }    private buildSnapshot(room: Room, viewer?: Player | Spectator): RoomSnapshot {     const viewerSeat = viewer && "seat" in viewer ? viewer.seat : undefined;     return {       roomCode: room.code,       revision: room.revision,       phase: room.phase,       viewerRole: viewer ? ("seat" in viewer ? "player" : "spectator") : undefined,       players: [...room.players]         .sort((left, right) => left.seat - right.seat)         .map((player) => ({           id: player.id,           name: player.name,           avatar: player.avatar,           seat: player.seat,           ready: player.ready,           connected: player.connected,           isHost: player.id === room.hostPlayerId,           isTestPlayer: player.isTestPlayer,           autoManaged: player.autoManaged,       })),       spectators: [...room.spectators].map((spectator) => ({         id: spectator.id,         name: spectator.name,         avatar: spectator.avatar,         connected: spectator.connected,         requestingSeat: spectator.requestingSeat,       })),       scoreTotals: [...room.scoreTotals],       publicActions: room.publicActions.map((action) => ({         ...action,         seats: action.seats ? [...action.seats] : undefined,       })),       match: {         totalRounds: room.totalRounds,         startScore: room.startScore,         completedRounds: room.completedRounds,         status: room.matchEndReason ? "completed" : room.phase === "playing" ? "active" : "waiting",         endReason: room.matchEndReason,         rankings: room.matchEndReason ? this.calculateRankings(room.scoreTotals) : undefined,         roundHistory: room.roundHistory.map((round) => ({           ...round,           winnerSeats: [...round.winnerSeats],           scoreDeltas: [...round.scoreDeltas],           scoreTotals: [...round.scoreTotals],         })),         earlySettlement: room.earlySettlement           ? {               requesterSeat: room.earlySettlement.requesterSeat,               duringRound: room.earlySettlement.duringRound,               status: room.earlySettlement.status,               approvedSeats: [...room.earlySettlement.responses.entries()].filter(([, agree]) => agree).map(([seat]) => seat),               rejectedSeats: [...room.earlySettlement.responses.entries()].filter(([, agree]) => !agree).map(([seat]) => seat),               waitingSeats: room.earlySettlement.status === "voting"                 ? room.players.map((player) => player.seat).filter((seat) => !room.earlySettlement?.responses.has(seat))                 : [],             }           : undefined,       },       game: room.game         ? {             modelVersion: room.game.modelVersion,             roundNumber: room.game.roundNumber,             dealerSeat: room.game.dealerSeat,             turnSeat: room.game.turnSeat,             stage: room.game.stage,             wallRemaining: room.game.wall.length,             wallRemainingBySeat: wallCountsForGame(room.game),             handTileCounts: [0, 1, 2, 3].map((seat) => room.game?.hands.get(seat)?.length ?? 0),             actionDeadlineAt: room.actionDeadlineAt,             actionTimeoutSeconds: room.game.stage === "awaiting_reactions" ? REACTION_TIMEOUT_MS / 1_000 : room.game.stage === "awaiting_discard" ? DISCARD_TIMEOUT_MS / 1_000 : undefined,             viewerSeat,             selfHand: viewerSeat === undefined ? undefined : sortTiles(room.game.hands.get(viewerSeat) ?? []).map((tile) => tile.code),             selfDrawnTile: viewerSeat !== undefined && room.game.lastDraw?.seat === viewerSeat ? room.game.lastDraw.tile.code : undefined,             selfDiscardRestrictedTile: viewerSeat !== undefined && room.game.discardRestriction?.seat === viewerSeat ? room.game.discardRestriction.tile : undefined,             latestDiscard: room.game.discards.at(-1),             discards: [...room.game.discards],             melds: [...room.game.melds.values()].flat().map((meld) =>               meld.gangType === "an" && viewerSeat !== meld.seat                 ? { ...meld, tiles: [], hiddenTileCount: meld.tiles.length }                 : { ...meld },             ),             scorePayments: [...room.game.scorePayments],             scoreDeltas: [...room.game.scoreDeltas],             reaction: room.game.pendingReaction               ? {                   discard: room.game.pendingReaction.discard,                   source: room.game.pendingReaction.source,                   waitingCount: [...room.game.pendingReaction.optionsBySeat.keys()].filter(                     (seat) => !room.game?.pendingReaction?.responses.has(seat),                   ).length,                   respondedCount: room.game.pendingReaction.responses.size,                 }               : undefined,             availableOperations:               viewerSeat !== undefined && room.game.pendingReaction && !room.game.pendingReaction.responses.has(viewerSeat)                 ? room.game.pendingReaction.optionsBySeat.get(viewerSeat)                 : undefined,             availableTurnOperations:               viewerSeat !== undefined && room.game.stage === "awaiting_discard" && room.game.turnSeat === viewerSeat                 ? findTurnOperationOptions(                     room.game.hands.get(viewerSeat) ?? [],                     viewerSeat,                     room.game.melds.get(viewerSeat) ?? [],                     room.game.lastDraw,                     room.game.wall.length,                   )                 : undefined,             roundResult: room.game.roundResult               ? {                   ...room.game.roundResult,                   payments: room.game.roundResult.payments ?? [...room.game.scorePayments],                   scoreDeltas: room.game.roundResult.scoreDeltas ?? [...room.game.scoreDeltas],                 }               : undefined,           }         : undefined,     };   }    private maybeAdvanceTestDealer(room: Room): RoomSnapshot | undefined {     if ((this.options.testPlayerTurnMs ?? 0) > 0) {       this.scheduleTestPlayer(room);       return undefined;     }     return this.autoDiscardTestDealer(room);   }    private scheduleTestPlayer(room: Room): void {     const game = room.game;     if (!game || game.stage !== "awaiting_discard") return;     const player = room.players.find((candidate) => candidate.seat === game.turnSeat);     if (!player?.isTestPlayer) return;     room.testPlayerAutoDueAt = this.now() + (this.options.testPlayerTurnMs ?? TEST_PLAYER_TURN_MS);   }    private autoDiscardTestDealer(room: Room): RoomSnapshot | undefined {     const game = room.game;     if (!game || game.stage !== "awaiting_discard") return undefined;     const dealer = room.players.find((player) => player.seat === game.dealerSeat && player.isTestPlayer);     if (!dealer) return undefined;     return this.autoPlayTestTurn(room, dealer.seat).snapshot;   }    private pickTestReactionOption(options: readonly ReactionOption[]): ReactionOption | undefined {     for (const kind of ["hu", "gang", "peng", "chi"] as const) {       const option = options.find((candidate) => candidate.kind === kind);       if (option) return option;     }     return undefined;   }    private pickTestTurnOperation(game: InitialGameState, seat: number): TurnOperationOption | undefined {     const hand = game.hands.get(seat) ?? [];     const melds = game.melds.get(seat) ?? [];     const options = findTurnOperationOptions(hand, seat, melds, game.lastDraw, game.wall.length);     for (const kind of ["zimo", "angang", "jiagang", "specialgang", "zhangmao"] as const) {       const option = options.find((candidate) => candidate.kind === kind);       if (option) return option;     }     return undefined;   }    private autoPlayTestTurn(room: Room, seat: number): { snapshot: RoomSnapshot; playedTile?: TileCode; automaticTurnCount: number } {     const player = room.players.find((candidate) => candidate.seat === seat && candidate.isTestPlayer);     if (!player) throw new Error("测试玩家不存在");     const game = room.game;     if (!game || game.stage !== "awaiting_discard" || game.turnSeat !== seat) {       return { snapshot: this.snapshot(room.code), automaticTurnCount: 0 };     }     let snapshot = this.snapshot(room.code);     let playedTile: TileCode | undefined;     let automaticTurnCount = 0;     const operation = this.pickTestTurnOperation(game, seat);     if (operation) {       const progress = this.performTurnOperation(room.code, player.token, operation.id);       snapshot = progress.snapshot;       playedTile = progress.diagnostics.tile;       if (room.game?.stage === "round_ended") return { snapshot, playedTile, automaticTurnCount: 0 };     }     if (room.game?.stage === "awaiting_discard" && room.game.turnSeat === seat) {       const tile = this.pickAutomaticDiscardTile(room.game, seat);       const progress = this.discardTile(room.code, player.token, tile);       snapshot = progress.snapshot;       playedTile = tile;       automaticTurnCount = progress.diagnostics.autoDiscards.length;     }     return { snapshot, playedTile, automaticTurnCount };   }    private progressFromDiscard(     room: Room,     initialDiscard: DiscardView,     progress: AutomaticProgress,     initialReactionResolved = false,   ): void {     const game = room.game;     if (!game) throw new Error("牌局状态不存在");     room.testPlayerAutoDueAt = undefined;     let discard = initialDiscard;     let reactionResolved = initialReactionResolved;      while (true) {       if (!reactionResolved) {         const optionsBySeat = new Map<number, ReactionOption[]>();         for (const candidate of room.players) {           if (candidate.seat === discard.seat) continue;           const hand = game.hands.get(candidate.seat) ?? [];           const options = findDiscardReactionOptions(hand, candidate.seat, discard, game.melds.get(candidate.seat) ?? [], game.wall.length);           if (options.length > 0) optionsBySeat.set(candidate.seat, options);         }         const responderSeats = [...optionsBySeat.keys()];         const testResponderSeats = responderSeats.filter((seat) => room.players.find((player) => player.seat === seat)?.isTestPlayer);         const autoPassedSeats = testResponderSeats.filter((seat) => this.pickTestReactionOption(optionsBySeat.get(seat) ?? []) === undefined);         const humanResponderSeats = responderSeats.filter((seat) => !testResponderSeats.includes(seat));         progress.reactionWindows.push({           discard,           eligibleSeats: responderSeats,           optionCount: [...optionsBySeat.values()].reduce((sum, options) => sum + options.length, 0),           autoPassedSeats,           awaitingSeats: humanResponderSeats,           resolution: humanResponderSeats.length > 0 ? "awaiting_players" : "advance_turn",         });          if (responderSeats.length > 0) {           game.pendingReaction = { discard, source: "discard", optionsBySeat, responses: new Map() };           game.stage = "awaiting_reactions";           game.lastDraw = undefined;           for (const seat of testResponderSeats) {             const responder = room.players.find((candidate) => candidate.seat === seat);             if (!responder) throw new Error("测试响应玩家不存在");             const option = this.pickTestReactionOption(optionsBySeat.get(seat) ?? []);             this.reactToDiscard(room.code, responder.token, option?.id ?? "pass");           }           if (humanResponderSeats.length > 0) return;           if ((this.options.testPlayerTurnMs ?? 0) <= 0 && (game.stage as InitialGameState["stage"]) === "awaiting_discard") {             const claimedPlayer = room.players.find((candidate) => candidate.seat === game.turnSeat);             if (claimedPlayer?.isTestPlayer) this.autoPlayTestTurn(room, claimedPlayer.seat);           }           return;         }       }        game.pendingReaction = undefined;       const nextSeat = (discard.seat + 1) % 4;       const drawnTile = drawTileFromWall(game, nextSeat);       if (!drawnTile) return;       const nextPlayer = room.players.find((candidate) => candidate.seat === nextSeat);       if (!nextPlayer) throw new Error("下一回合玩家不存在");       if (!nextPlayer.isTestPlayer) return;       if ((this.options.testPlayerTurnMs ?? 0) > 0) {         this.scheduleTestPlayer(room);         return;       }       this.autoPlayTestTurn(room, nextSeat);       return;     }   }    private applyMeldClaim(game: InitialGameState, discard: DiscardView, seat: number, option: ReactionOption): MeldView {     const hand = game.hands.get(seat);     if (!hand) throw new Error("操作玩家手牌不存在");     for (const code of option.consumeTiles) {       const index = hand.findIndex((tile) => tile.code === code);       if (index < 0) throw new Error("操作所需手牌不存在");       hand.splice(index, 1);     }     const latestDiscard = game.discards.at(-1);     if (!latestDiscard || latestDiscard.seat !== discard.seat || latestDiscard.tile !== discard.tile) {       throw new Error("待响应弃牌与牌桌状态不一致");     }     game.discards.pop();     const meld: MeldView = {       seat,       kind: option.kind as MeldView["kind"],       tiles: option.displayTiles,       fromSeat: discard.seat,       ...(option.kind === "gang" ? { gangType: "ming" as const } : {}),     };     game.melds.get(seat)?.push(meld);     game.pendingReaction = undefined;     game.lastDraw = undefined;     game.discardRestriction = option.kind === "chi" ? { seat, tile: discard.tile } : undefined;     game.turnSeat = seat;     if (option.kind === "gang") drawTileFromWallEnd(game, seat);     else game.stage = "awaiting_discard";     return meld;   }    private finalizePendingKong(     game: InitialGameState,     pendingKong: NonNullable<NonNullable<InitialGameState["pendingReaction"]>["pendingKong"]>,   ): MeldView {     const playerMelds = game.melds.get(pendingKong.seat);     if (!playerMelds) throw new Error("杠牌玩家的副露不存在");     let meld: MeldView;     if (pendingKong.type === "jiagang") {       const original = playerMelds[pendingKong.meldIndex ?? -1];       const tile = pendingKong.tiles[0];       if (!original || original.kind !== "peng" || !tile || original.tiles[0] !== tile.code) throw new Error("原碰牌组与加杠状态不一致");       original.kind = "gang";       original.gangType = "jia";       original.tiles = [...original.tiles, tile.code];       meld = original;     } else if (pendingKong.type === "specialgang") {       if (!pendingKong.specialType) throw new Error("特殊杠类型不存在");       const allTiles = pendingKong.tiles.map((tile) => tile.code);       const growthCount = pendingKong.specialType === "winds"         ? Math.max(0, allTiles.length - 4)         : Math.max(0, allTiles.length - 3);       meld = {         seat: pendingKong.seat,         kind: "special_gang",         tiles: allTiles,         fromSeat: pendingKong.seat,         specialType: pendingKong.specialType,         growthCount,       };       playerMelds.push(meld);     } else {       const original = playerMelds[pendingKong.meldIndex ?? -1];       const tile = pendingKong.tiles[0];       if (!original || original.kind !== "special_gang" || !original.specialType || !tile) throw new Error("原特殊杠与涨毛状态不一致");       original.tiles = [...original.tiles, tile.code];       original.growthCount = (original.growthCount ?? 0) + 1;       meld = original;     }     game.pendingReaction = undefined;     game.lastDraw = undefined;     game.turnSeat = pendingKong.seat;     if (pendingKong.type === "specialgang") {       const replacementCount = Math.max(0, pendingKong.tiles.length - 3);       for (let growth = 0; growth < replacementCount; growth += 1) {         drawTileFromWallEnd(game, pendingKong.seat);       }       game.stage = "awaiting_discard";     } else {       drawTileFromWallEnd(game, pendingKong.seat);     }     return meld;   }    private restoreUnrobbedKongTiles(     game: InitialGameState,     pendingKong: NonNullable<NonNullable<InitialGameState["pendingReaction"]>["pendingKong"]>,   ): void {     const hand = game.hands.get(pendingKong.seat);     if (!hand) throw new Error("被抢杠玩家手牌不存在");     let robbedTileRemoved = false;     for (const tile of pendingKong.tiles) {       if (!robbedTileRemoved && tile.code === pendingKong.robTile) {         robbedTileRemoved = true;         continue;       }       hand.push(tile);     }     if (!robbedTileRemoved) throw new Error("抢杠牌不在待确认牌组中");   }    private pickAutomaticDiscardTile(game: InitialGameState, seat: number): TileCode {     const hand = game.hands.get(seat) ?? [];     const sortedCodes = sortTiles(hand).map((tile) => tile.code);     const drawn = game.lastDraw?.seat === seat ? game.lastDraw.tile.code : undefined;     const candidates = drawn ? [drawn, ...sortedCodes.filter((code) => code !== drawn)] : sortedCodes;     const restricted = game.discardRestriction?.seat === seat ? game.discardRestriction.tile : undefined;     const tile = candidates.find((code) => code !== restricted);     if (!tile) throw new Error("自动出牌时没有可打出的手牌");     return tile;   }    private removeTilesFromHand(hand: Tile[], codes: readonly TileCode[]): void {     this.takeTilesFromHand(hand, codes);   }    private takeTilesFromHand(hand: Tile[], codes: readonly TileCode[]): Tile[] {     const remaining = [...hand];     const taken: Tile[] = [];     for (const code of codes) {       const index = remaining.findIndex((tile) => tile.code === code);       if (index < 0) throw new Error("操作所需手牌不存在");       taken.push(remaining.splice(index, 1)[0]!);     }     hand.splice(0, hand.length, ...remaining);     return taken;   }    private finalizeEarlySettlement(room: Room): void {     const game = room.game;     if (!game) throw new Error("提前结算时牌局状态不存在");     room.matchEndReason = "early_agreement";     this.clearActionDeadline(room);     if (game.stage === "round_ended") return;     game.pendingReaction = undefined;     game.lastDraw = undefined;     game.stage = "round_ended";     game.roundResult = {       reason: "dissolved",       winnerSeats: [],       payments: [...game.scorePayments],       scoreDeltas: [...game.scoreDeltas],     };     this.recordPublicAction(room, { kind: "round_dissolved" });   }    private ensureActionDeadline(room: Room, force = false): void {     const game = room.game;     if (!game || room.matchEndReason || room.earlySettlement?.status === "voting" || game.stage === "round_ended") {       this.clearActionDeadline(room);       return;     }     const stateKey = game.stage === "awaiting_discard"       ? `discard:${game.roundNumber}:${game.turnSeat}:${game.discards.length}`       : `reaction:${game.roundNumber}:${game.pendingReaction?.source}:${game.pendingReaction?.discard.seat}:${game.pendingReaction?.discard.tile}:${game.discards.length}`;     if (!force && room.actionStateKey === stateKey && room.actionDeadlineAt !== undefined) return;     room.actionStateKey = stateKey;     room.actionDeadlineAt = this.now() + (game.stage === "awaiting_reactions" ? REACTION_TIMEOUT_MS : DISCARD_TIMEOUT_MS);   }    private clearActionDeadline(room: Room): void {     room.actionDeadlineAt = undefined;     room.actionStateKey = undefined;   }    private recordKongPayments(     room: Room,     seat: number,     operation: "gang" | "angang" | "jiagang" | "specialgang" | "zhangmao",     growthCount = 0,   ): void {     const reason = operation === "gang"       ? "ming_gang"       : operation === "angang"         ? "an_gang"         : operation === "jiagang"           ? "jia_gang"           : operation === "specialgang"             ? "special_gang"             : "zhangmao";     this.recordPayments(room, calculateKongPayments(seat, reason));     for (let growth = 0; growth < growthCount; growth += 1) {       this.recordPayments(room, calculateKongPayments(seat, "zhangmao"));     }   }    private recordPayments(room: Room, payments: readonly ScorePaymentView[]): void {     const game = room.game;     if (!game) throw new Error("计分时牌局状态不存在");     const deltas = calculateScoreDeltas(payments);     game.scorePayments.push(...payments);     for (let seat = 0; seat < 4; seat += 1) {       game.scoreDeltas[seat] = (game.scoreDeltas[seat] ?? 0) + (deltas[seat] ?? 0);       room.scoreTotals[seat] = (room.scoreTotals[seat] ?? room.startScore) + (deltas[seat] ?? 0);     }   }    private recordPublicAction(     room: Room,     action: Omit<PublicActionView, "sequence" | "roundNumber"> & { roundNumber?: number },   ): void {     room.publicActions.push({       sequence: room.nextActionSequence,       roundNumber: action.roundNumber ?? room.game?.roundNumber,       ...action,     });     room.nextActionSequence += 1;     if (room.publicActions.length > 200) room.publicActions.splice(0, room.publicActions.length - 200);   }    private recordRoundEndedAction(room: Room): void {     const game = room.game;     if (!game || game.stage !== "round_ended" || !game.roundResult) return;     const latest = room.publicActions.at(-1);     if (latest?.kind === "round_ended" && latest.roundNumber === game.roundNumber) return;     this.recordPublicAction(room, { kind: "round_ended", seats: [...game.roundResult.winnerSeats] });   }    private publicKindForMeld(meld: MeldView): PublicActionKind {     if (meld.kind === "chi") return "chi";     if (meld.kind === "peng") return "peng";     if (meld.kind === "special_gang") return meld.growthCount ? "zhangmao" : "special_gang";     if (meld.gangType === "an") return "an_gang";     if (meld.gangType === "jia") return "jia_gang";     return "ming_gang";   }    private updateMatchAfterRound(room: Room): void {     const game = room.game;     if (!game || game.stage !== "round_ended" || room.completedRounds >= game.roundNumber) return;     if (!game.roundResult) throw new Error("本局结束时缺少结算结果");     room.completedRounds = game.roundNumber;     room.roundHistory.push({       roundNumber: game.roundNumber,       dealerSeat: game.dealerSeat,       reason: game.roundResult.reason,       winnerSeats: [...game.roundResult.winnerSeats],       scoreDeltas: [...game.scoreDeltas],       scoreTotals: [...room.scoreTotals],     });     if (room.scoreTotals.some((score) => score < 0)) {       room.matchEndReason = "negative_score";       return;     }     if (room.completedRounds >= room.totalRounds) {       room.matchEndReason = "round_limit";       return;     }     for (const player of room.players) {       player.ready = player.isTestPlayer;     }   }    private calculateRankings(scoreTotals: readonly number[]): MatchRankingView[] {     return scoreTotals       .map((score, seat) => ({ seat, score, rank: 1 + scoreTotals.filter((candidate) => candidate > score).length }))       .sort((left, right) => left.rank - right.rank || left.seat - right.seat);   }    private normalizeStartScore(value: number): number {     if (!Number.isInteger(value) || value < START_SCORE_MIN || value > START_SCORE_MAX) {       throw new RoomError("START_SCORE_INVALID", `开局分需为${START_SCORE_MIN}到${START_SCORE_MAX}的整数`);     }     return value;   }    private getRoom(rawCode: string): Room {     const code = this.normalizeCode(rawCode);     const room = this.rooms.get(code);     if (!room) throw new RoomError("ROOM_NOT_FOUND", "没有找到这个房间");     return room;   }    private toSession(room: Room, player: Player): Session {     return {       roomCode: room.code,       playerId: player.id,       playerToken: player.token,       role: "player",       snapshot: this.snapshotForPlayer(room.code, player.token),     };   }    private createPlayer(name: string, seat: number, isTestPlayer = false, avatar = DEFAULT_AVATAR): Player {     return {       id: randomUUID(),       token: randomUUID(),       name,       avatar: this.normalizeAvatar(avatar),       seat,       ready: false,       connected: true,       isTestPlayer,       autoManaged: false,     };   }    private createSpectator(name: string, avatar = DEFAULT_AVATAR): Spectator {     return {       id: randomUUID(),       token: randomUUID(),       name,       avatar: this.normalizeAvatar(avatar),       connected: true,       requestingSeat: false,       joinedAt: this.now(),     };   }    private createCode(): string {     for (let attempt = 0; attempt < 100; attempt += 1) {       const code = randomInt(100000, 1000000).toString();       if (!this.rooms.has(code)) return code;     }     throw new RoomError("CODE_EXHAUSTED", "暂时无法创建房间，请稍后再试");   }    private normalizeCode(rawCode: string): string {     return rawCode.trim();   }    private normalizeName(rawName: string): string {     const name = rawName.trim().slice(0, 12);     if (!name) throw new RoomError("NAME_REQUIRED", "请输入昵称");     return name;   }    private normalizeAvatar(rawAvatar: unknown): string {     if (typeof rawAvatar !== "string" || !AVATAR_IDS.includes(rawAvatar as (typeof AVATAR_IDS)[number])) return DEFAULT_AVATAR;     return rawAvatar;   } }